rejected'?'status-rejected':'status-pending')?>"><strong><?=htmlspecialchars($p['dept_name'])?></strong><br><?=htmlspecialchars($status)?></div><?php endforeach;?></div></div></section><?php require_once __DIR__.'/../includes/footer.php';?>
